    11	        
    12	        const sig = new SignedXml();
    13	        sig.privateKey = this.privateKey;
    14	        
    15	        sig.addReference({
    16	            xpath: `//*[@ID="${assertionID}"]`,
    17	            transforms: [
    18	                'http://www.w3.org/2000/09/xmldsig#enveloped-signature',
    19	                'http://www.w3.org/2001/10/xml-exc-c14n#'
    20	            ],
    21	            digestAlgorithm: 'http://www.w3.org/2001/04/xmlenc#sha256'
    22	        });
    23	        
    24	        sig.canonicalizationAlgorithm = 'http://www.w3.org/2001/10/xml-exc-c14n#';
    25	        sig.signatureAlgorithm = 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256';
    26	        
    27	        sig.keyInfoProvider = {
    28	            getKeyInfo: () => {
    29	                const certBody = this.certificate
    30	                    .replace(/-----BEGIN CERTIFICATE-----/, '')
    31	                    .replace(/-----END CERTIFICATE-----/, '')
    32	                    .replace(/\s/g, '');
    33	                
    34	                return '<X509Data><X509Certificate>' + certBody + '</X509Certificate></X509Data>';
    35	            }
    36	        };
    37	        
    38	        sig.computeSignature(xml, {
    39	            location: { reference: "//*[local-name(.)='Issuer']", action: 'after' }
    40	        });
