    45	    signResponse(responseXml, responseID, signedAssertion) {
    46	        const statusCloseTag = '</samlp:Status>';
    47	        const insertPos = responseXml.indexOf(statusCloseTag);
    48	        
    49	        if (insertPos === -1) {
